            let PROMOTION = {
                _wrap : document.querySelector('#protowrap'),
                _scrollTop : function(){
                    var scrollTop = window.scrollTop || document.documentElement.scrollTop || document.body.scrollTop;
                    return parseInt(scrollTop);
                },
                _scrollTo: function(offset, callback){
                    window.removeEventListener('scrollend', PROMOTION._scroller);
                    PROMOTION._scroller = ()=> { callback() }
                    window.addEventListener('scrollend', PROMOTION._scroller, {once: true});
                    window.scrollTo({
                        top: offset,
                        behavior: 'smooth',
                    });
                },
                _extend : function(){
                    let obj = {};
                    for (let i = 0; i < arguments.length; i++) {
                        obj = $.extend(true, obj, arguments[i]);
                    }
                    return obj;
                },
                Anchor : {
                    init : function(){
                        let self = this,
                            anchors = PROMOTION._wrap.querySelectorAll('[data-promotion="anchor"] a'),
                            root = PROMOTION._wrap.querySelector('[data-sticky-navi]'),
                            tabs = document.querySelectorAll('[data-promotion="anchor"]');

                        self.isScroll = false;

                        if (anchors.length < 1) return false;

                        anchors.forEach((el, idx)=>{
                            el.addEventListener('click', function( event ){
                                event.preventDefault();
                                let li = el.closest('li');
                                    sticky = el.closest('[data-promotion-anchor-sticky]'),
                                    stickyTop = sticky == null ? 0 : parseInt(getComputedStyle(sticky).getPropertyValue('top')),
                                    stickyPos = sticky == null ? 0 : sticky.offsetHeight,
                                    rootTop = root == null ? 0 : root.offsetHeight,
                                    topPos = parseInt(window.pageYOffset + document.getElementById(el.href.split("#")[1]).getBoundingClientRect().top - (rootTop + stickyPos + stickyTop)) + 10,
                                    index = Array.from(li.parentNode.children).indexOf(li);

                                if(topPos == PROMOTION._scrollTop()) return;

                                self.isScroll = true;

                                PROMOTION._scrollTo(topPos, ()=>{ self.isScroll = false });


                                anchors.forEach(elem=> {
                                    elem.closest('li').classList.remove('active');
                                })

                                tabs.forEach(tab => {
                                    let anc = tab.querySelectorAll('a');
                                    let li = anc[index].closest('li');
                                    li.classList.add('active');
                                    self.scroll(li, li.parentElement);
                                })
                            })
                        });

                        self.sticky(anchors);
                    },

                    sticky: function(anchors){
                        let self = this,
                            stickyTab = PROMOTION._wrap.querySelector('[data-promotion-anchor-sticky]'),
                            tabs = document.querySelectorAll('[data-promotion="anchor"]');

                            if(!stickyTab) return false;

                        let stickyTabScroll = stickyTab.children[0],
                            secEl = [...PROMOTION._wrap.querySelectorAll('[data-anchor-view]')];

                        document.addEventListener('scroll', ()=> {
                            if(self.isScroll) return false;
                            let top = PROMOTION._scrollTop(),
                                tabRectBottom = stickyTab.getBoundingClientRect().bottom,
                                activeIndex = secEl.length - 1;

                            secEl.some((sec, i)=> {
                                let rectBottom = sec.getBoundingClientRect().bottom;
                                if(tabRectBottom <= rectBottom){
                                    activeIndex = i;
                                    return true;
                                }
                            });
                            tabs.forEach(tab => {
                                let anc = tab.querySelectorAll('a');
                                let li = anc[activeIndex].closest('li');

                                if(li.classList.contains('active')) return;

                                [...anc[0].closest('ul').children].forEach(elem=> {
                                    elem.classList.remove('active');
                                })

                                li.classList.add('active')
                                this.scroll(li, stickyTabScroll);
                            });

                        })

                    },

                    scroll: function(li, scrollParent){
                        let scrollHalf = scrollParent.clientWidth / 2,
                            liHalf = li.clientWidth / 2,
                            scrollLeft = parseInt(li.offsetLeft - scrollParent.offsetLeft - scrollHalf + liHalf);

                        scrollParent.scrollTo({
                            behavior: "smooth",
                            left: scrollLeft
                        })
                    }
                },
                DayRange: {
                    init () {
                        const self = this, ranges = document.querySelectorAll('[data-promotion-range-item]');
                        if (ranges.length < 1) return;

                        function zeroCheck(value) {
                            return value >= 10 ? value : `0${value}`;
                        }

                        const basic = new Date();
                        const year = basic.getFullYear();
                        const month = zeroCheck(basic.getMonth() + 1);
                        const date = zeroCheck(basic.getDate());
                        const now = new Date(`${year}-${month}-${date}`);

                        ranges.forEach(el => {
                            let start = new Date(el.dataset.dayStart),
                                end = new Date(el.dataset.dayEnd);
                            if (now >= start && now <= end) {
                                // el.outerHTML = el.innerHTML;
                                el.classList.add('active');
                            }
                        });
                    }
                },
                Tab : {
                    init : function(){
                        let self = this, tab = document.querySelectorAll('[data-promotion="tab"]');
                        if (tab.length < 1) return;
                        tab.forEach(function(el, idx){
                            let caller = [...el.querySelectorAll('a')];
                            if (caller.length < 1) return;

                            caller.forEach(elem => {
                                elem.addEventListener('click', function( event ){
                                    event.preventDefault();
                                    let flag = elem.parentElement.nodeName == 'LI',
                                        button = flag ? elem.closest('li') : elem,
                                        buttons = flag ? caller.map(x => x.closest('li')) : caller,
                                        view = document.getElementById(elem.href.split("#")[1]),
                                        views = caller.map(x => document.getElementById(x.href.split("#")[1])),
                                        slider = view.querySelectorAll('[data-promotion="slider"]');

                                    // ON
                                    ;[].concat(buttons, views).forEach(x => x.classList.remove('on'));
                                    if (slider.length > 0) {
                                        slider.forEach(el => {
                                            el.swiper != undefined && el.swiper.destroy(true, true);
                                        });
                                        setTimeout(el => {
                                            PROMOTION.Slider.init(view);
                                        }, 100)
                                    }
                                    // OFF
                                    button.classList.add('on');
                                    view.classList.add('on');

                                });
                            })
                        });
                    }
                },
                Slider : {
                    default (slider){
                        let  _default, _required;

                        _default = {
                            slidesPerView :'auto',
                            slidesPerColumn: 2,
                            spaceBetween: 20,
                            observer: true,
                            observeParents: true,
                            observeSlideChildren: true,
                            watchSlidesVisibility: true,
                            watchOverflow:true,
                        };

                        _required = {
                            pagination: function(){
                                let pagination = slider.querySelector('.swiper-pagination');
                                if (!!!pagination) return;

                                return {
                                    pagination: {
                                        el: pagination,
                                        type: 'bullets',
                                    },
                                }
                            },
                            navigation: function(){
                                let next = slider.querySelector('[data-slide-control="next"]'),
                                    prev = slider.querySelector('[data-slide-control="prev"]');
                                if (!!!(next && prev)) return;

                                return {
                                    navigation: {
                                        nextEl: next,
                                        prevEl: prev,
                                    }
                                }
                            },
                        }

                        for (let opt in _required) {
                            _default = PROMOTION._extend(_default, _required[opt]());
                        }

                        return _default;
                    },
                    set (slider, idx){
                        const name = slider.dataset.promotionSliderName;
                        slider.set = {
                            slider: slider,
                            index: idx,
                            options: PROMOTION.Slider.default(slider),
                            condition: function(){
                                return true;
                            },
                            beforeHandler: function(){},
                            afterHandler: function(){},
                        };

                        function vwpx(vw){
                            return Math.round(((vw * window.innerWidth) / 100) * 10 / 10);
                        }

                        /*
                            커스텀 옵션
                            - 사용법 : data-promotion-slider-name="group" 이름을 지정하고 해당 이름으로 커스텀 옵션을 정의
                            - 여러개의 각기 다른 옵션을 사용할 경우 사용
                            - 한개만 사용하거나, 같은 옵션으로 모든 캐러셀이 대응될 경우 제외
                        */
                        const _custom = {
                            "gift": {
                                options: {
                                    slidesPerColumn: 3,
                                }
                            },
                            "pick": {
                                options: {
                                    spaceBetween: 15,
                                }
                            },
                        };

                        slider.set = PROMOTION._extend(slider.set, name != undefined ? _custom[name] : {});
                    },
                    init (slider = document){
                        let sliders = slider.querySelectorAll('[data-promotion="slider"]');
                        if (sliders.length < 1) return false;

                        sliders.forEach(function(el, idx){
                            PROMOTION.Slider.set(el, idx);
                            let set = el.set;

                            if (set.condition()) {
                                set.beforeHandler();
                                if (el.swiper !== undefined && el.swiper !== null) {
                                    el.swiper.update();
                                    return;
                                }
                                el.swiper = new Swiper(el.querySelector('.swiper-container'), set.options);

                                setTimeout(() => {
                                    set.afterHandler();
                                }, 100)
                            }
                        });
                    },
                },
            }
